<?php declare(strict_types=1); ?>
<section class="page-hero"><div class="shell"><span class="section-label light"><?= $e($t($page . '.hero.label')) ?></span><h1><?= $e($t($page . '.hero.title')) ?></h1><p><?= $e($t($page . '.hero.copy')) ?></p><?php if (!empty($heroActions)): ?><div class="hero-actions"><?php foreach ($heroActions as $action): ?><a class="button <?= $e($action['class']) ?>" href="<?= $e($action['href']) ?>"<?= !empty($action['external']) ? ' target="_blank" rel="noopener noreferrer"' : '' ?>><?= $e($action['label']) ?><?= $icon($action['icon'] ?? 'arrow-right') ?></a><?php endforeach; ?></div><?php endif; ?></div></section>
